use pizza_store;

-- Q1) What is the total revenue generated by pizza sales?

SELECT 
    SUM(p.price * od.quantity) AS total_revenue
FROM
    pizzas p
        JOIN
    order_details od ON p.pizza_id = od.pizza_id;


-- Q2) How many orders were placed?

SELECT 
    COUNT(DISTINCT (order_id)) AS Total_order
FROM
    orders;

-- Q3) Which pizza category generates the highest revenue?

SELECT 
    pt.category, SUM(od.quantity * p.price) AS highest_revenue
FROM
    order_details od
        JOIN
    pizzas p ON od.pizza_id = p.pizza_id
        JOIN
    pizza_types pt ON pt.pizza_type_id = p.pizza_type_id
GROUP BY pt.category
ORDER BY highest_revenue DESC
LIMIT 1;

-- Which are the top 5 best-selling pizzas by quantity?

SELECT 
    pt.pizza_name, SUM(od.quantity) AS total_quantity
FROM
    pizzas p
        JOIN
    order_details od ON p.pizza_id = od.pizza_id
        JOIN
    pizza_types pt ON pt.pizza_type_id = p.pizza_type_id
GROUP BY pt.pizza_name
ORDER BY total_quantity DESC
LIMIT 5;

-- Q5) Which month generates the highest revenue?

SELECT 
    MONTH(o.order_date) AS month_number,
    MONTHNAME(o.order_date) AS month_name,
    SUM(p.price * od.quantity) AS highest_revenue
FROM
    order_details od
        JOIN
    orders o ON od.order_id = o.order_id
        JOIN
    pizzas p ON p.pizza_id = od.pizza_id
GROUP BY MONTH(o.order_date) , MONTHNAME(o.order_date)
ORDER BY highest_revenue DESC
LIMIT 1;

-- Q6) What is the average order value?

SELECT 
    SUM(p.price * od.quantity) / COUNT(DISTINCT o.order_id) AS average_order_value
FROM
    order_details od
        JOIN
    pizzas p ON p.pizza_id = od.pizza_id
        JOIN
    orders o ON o.order_id = od.order_id;
    
    
-- Q7) What is the sales contribution of each pizza category?

with category_sales as(select pt.category, sum(p.price * od.quantity) as total_revenue
from pizza_types pt join pizzas p on p.pizza_type_id = pt. pizza_type_id
join order_details od on p.pizza_id = od.pizza_id
group by pt.category) 
select category, total_revenue, round(total_revenue * 100/ sum(total_revenue) over()) as contribution_percentage
from category_sales;

